import { Stage, Layer, Rect, Text } from "konva";
import { scale, intersect, verticesArray, isPointInsidePolygon } from ".";

export function fillWallWithTiles(polygon, tileWidth, tileHeight, gap) {
  //TODO Set the dimensions of the canvas based on the polygon's points
  const stage = new Stage({
    container: document.getElementById("app"),
    width: window.innerWidth,
    height: window.innerHeight,
    draggable: false,
    pos: 1000
  });
  stage.scale({ x: scale, y: scale });

  const layer = new Layer();
  stage.add(layer);

  const testRect = new Rect({
    x: 839.33,
    y: 68.19999999999999,
    width: 800,
    height: 200,
    fill: "blue",
    stroke: "black",
    strokeWidth: 1
    //points: [testRect.x(),0,0,0,0,0,0,0]
  });

  //console.log(testRect.attrs.points[0]);
  // Add the polygon to the layer
  layer.add(polygon);
  //layer.add(testRect);
  // Add the layer to the stage
  stage.add(layer);

  //testRect.intersects(0,0,0,0);
  stage.batchDraw();
  // Initialize the x and y coordinates of the FIRST tile, top left right now
  var x = 0;
  var y = 0;
  var rowCount = 0;

  var counterY = 0;

  // Keep placing tiles until the polygon is filled
  while (y < 5000) {
    // Check if the current position is inside the polygon
    counterY++;
    if (x < 20000) {
      var tile = new Rect({
        x: x,
        y: y,
        width: tileWidth,
        height: tileHeight,
        fill: "transparent",
        stroke: "black",
        strokeWidth: 1,
        points: [
          x,
          y,
          x + tileWidth,
          y,
          x + tileWidth,
          y + tileHeight,
          x,
          y + tileHeight
        ]
      });
      //console.log(tile.attrs.points);
      var text = new Text({
        x: x + tileWidth / 3,
        y: y + tileHeight / 3,
        fontSize: 30,
        fill: "black"
        //text: `x:${x} y:${y}`
      });
      for (let i = 0; i < 8; i += 2) {
        for (let j = 0; j < 8; j += 2) {
          var intersection = intersect(
            verticesArray[i],
            verticesArray[i + 1],
            verticesArray[i + 2],
            verticesArray[i + 3],
            tile.attrs.points[j],
            tile.attrs.points[j + 1],
            tile.attrs.points[j + 2],
            tile.attrs.points[j + 3]
          );
          if (intersection.x) {
            //console.log(intersection);
            let intersectionPoint = new Rect({
              x: intersection.x,
              y: intersection.y,
              height: 10,
              width: 10,
              fill: "red"
            });

            polygon.getParent().add(intersectionPoint);
          }
        }

        var json = stage.toJSON();
        // To save the JSON string to local storage or send it to a server
        localStorage.setItem('konva_stage', json);
        console.log("JSON\n" + json);
      }

      //each one of these should push to an array if true in their proper place in the array to be made into a line. It doesn't matter as long as they're in order, how do you do that for notches?
      if (isPointInsidePolygon(verticesArray, tile.attrs.x, tile.attrs.y) ||
        isPointInsidePolygon(
          verticesArray,
          tile.attrs.x,
          tile.attrs.y + tile.attrs.height
        ) ||
        isPointInsidePolygon(
          verticesArray,
          tile.attrs.x + tile.attrs.width,
          tile.attrs.y
        ) ||
        isPointInsidePolygon(
          verticesArray,
          tile.attrs.x + tile.attrs.width,
          tile.attrs.y + tile.attrs.height
        )) {
        polygon.getParent().add(tile);
        polygon.getParent().add(text);
      }
    }

    // Move the x coordinate to the right by the width of the tile plus the gap
    x += tileWidth + gap;

    // If the x coordinate is past the right edge of the polygon, move to the next row
    if (x >= 800) {
      rowCount++;
      //this part does the subway tile pattern
      if (rowCount % 2) {
        x = -tileWidth / 2;
      } else {
        x = 0;
      }
      y += tileHeight + gap;
    }
  }
}
